import{_ as a,o as r,c as i,a3 as o}from"./chunks/framework.Bh_aNVBG.js";const e="/images/project-admin/%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8_%EA%B4%80%EB%A6%AC_%ED%8E%98%EC%9D%B4%EC%A7%80.png",l="/images/project-admin/image%204.png",d="/images/project-admin/image%205.png",n="/images/project-admin/image%206.png",p="/images/project-admin/image%207.png",h="/images/project-admin/image%208.png",s="/images/project-admin/image%209.png",g="/images/project-admin/image%2010.png",c="/images/project-admin/image%2011.png",m="/images/project-admin/image%2012.png",j=JSON.parse('{"title":"3. 프로젝트 설정 및 관리","description":"","frontmatter":{},"headers":[],"relativePath":"project-admin/chapter-3.md","filePath":"project-admin/chapter-3.md"}'),_={name:"project-admin/chapter-3.md"};function b(u,t,q,k,P,f){return r(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="_3-프로젝트-설정-및-관리" tabindex="-1">3. 프로젝트 설정 및 관리 <a class="header-anchor" href="#_3-프로젝트-설정-및-관리" aria-label="Permalink to &quot;3. 프로젝트 설정 및 관리&quot;">​</a></h1><p>인포디오에서는 축제 및 행사별로 독립적인 프로젝트를 운영할 수 있습니다.</p><p>프로젝트는 인포디오 운영사에서 생성하여 고객사에 제공하며, 고객사는 할당받은 프로젝트의 기본 정보, 디자인, 서비스 기능 및 하단 내비게이션 등을 직접 설정할 수 있습니다.</p><p>본 장에서는 프로젝트를 전달받은 후 안내 페이지 운영을 위해 필요한 초기 설정 방법을 안내합니다.</p><h2 id="_3-1-프로젝트-관리-화면-진입" tabindex="-1">3.1. 프로젝트 관리 화면 진입 <a class="header-anchor" href="#_3-1-프로젝트-관리-화면-진입" aria-label="Permalink to &quot;3.1. 프로젝트 관리 화면 진입&quot;">​</a></h2><p>CMS에서 설정할 프로젝트를 선택하여 관리 화면으로 이동합니다.</p><h3 id="_1-프로젝트-선택" tabindex="-1">① 프로젝트 선택 <a class="header-anchor" href="#_1-프로젝트-선택" aria-label="Permalink to &quot;① 프로젝트 선택&quot;">​</a></h3><ol><li>CMS에 로그인합니다.</li><li><strong>프로젝트 관리</strong> 화면에서 할당된 프로젝트를 확인합니다.</li><li>관리할 프로젝트의 <strong>관리</strong> 버튼을 클릭합니다.</li><li>프로젝트 관리 화면으로 이동합니다.</li></ol><p><img src="'+e+'" alt="프로젝트 관리 페이지.png"></p><hr><h2 id="_3-2-프로젝트-기본-정보-설정" tabindex="-1">3.2. 프로젝트 기본 정보 설정 <a class="header-anchor" href="#_3-2-프로젝트-기본-정보-설정" aria-label="Permalink to &quot;3.2. 프로젝트 기본 정보 설정&quot;">​</a></h2><p>프로젝트 관리 화면에서 <strong>프로젝트 설정(Project Setting)</strong> 메뉴로 이동하여 프로젝트의 행사명, 행사 기간, 운영 상태 및 담당자 정보를 확인하고 수정할 수 있습니다.</p><p><img src="'+l+'" alt="image.png"></p><h3 id="_1-기본-정보-설정" tabindex="-1">① 기본 정보 설정 <a class="header-anchor" href="#_1-기본-정보-설정" aria-label="Permalink to &quot;① 기본 정보 설정&quot;">​</a></h3><ol><li>상단의 <strong>기본 정보</strong> 항목을 선택합니다.</li><li>변경할 정보를 입력합니다.</li><li>화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><img src="'+d+'" alt="image.png"></p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th><th>변경 가능 여부</th></tr></thead><tbody><tr><td>행사명</td><td>축제 또는 행사의 이름</td><td>가능</td></tr><tr><td>슬러그(URL)</td><td>안내 페이지에 사용되는 접속 주소</td><td>불가</td></tr><tr><td>행사 기간</td><td>행사 시작일 및 종료일</td><td>가능</td></tr><tr><td>상태</td><td>프로젝트 운영 상태</td><td>가능</td></tr><tr><td>담당자 정보</td><td>이름, 소속, 직책 및 연락처</td><td>가능</td></tr></tbody></table><blockquote><p><strong>주의사항</strong></p><p>슬러그(URL)는 프로젝트 생성 시 설정되며, 고객사는 직접 변경할 수 없습니다.</p><p>접속 주소 변경이 필요한 경우 인포디오 운영사에 문의해 주세요.</p></blockquote><hr><h2 id="_3-3-프로젝트-브랜딩-설정" tabindex="-1">3.3. 프로젝트 브랜딩 설정 <a class="header-anchor" href="#_3-3-프로젝트-브랜딩-설정" aria-label="Permalink to &quot;3.3. 프로젝트 브랜딩 설정&quot;">​</a></h2><p>브랜딩 설정에서는 안내 페이지에 적용할 로고, 대표 색상, 강조 색상 및 글꼴을 변경할 수 있습니다.</p><p>축제 또는 행사의 브랜드 이미지에 맞는 디자인을 적용하여 방문객에게 일관된 화면을 제공할 수 있습니다.</p><h3 id="_1-브랜딩-설정-화면-이동" tabindex="-1">① 브랜딩 설정 화면 이동 <a class="header-anchor" href="#_1-브랜딩-설정-화면-이동" aria-label="Permalink to &quot;① 브랜딩 설정 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>프로젝트 설정</strong> 메뉴로 이동합니다.</li><li>상단의 <strong>브랜딩</strong> 항목을 선택합니다.</li><li>현재 적용된 로고, 색상 및 글꼴을 확인합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><h3 id="_2-로고-설정" tabindex="-1">② 로고 설정 <a class="header-anchor" href="#_2-로고-설정" aria-label="Permalink to &quot;② 로고 설정&quot;">​</a></h3><p>안내 페이지에서 사용할 로고 또는 심볼 이미지를 등록할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>로고 / 심볼 이미지</strong> 항목으로 이동합니다.</li><li>이미지 파일을 선택하여 등록합니다.</li><li>기존 로고가 있는 경우 <strong>첨부 파일 변경</strong>을 통해 변경합니다.</li><li>설정을 저장합니다.</li></ol><h3 id="_3-테마-색상-설정" tabindex="-1">③ 테마 색상 설정 <a class="header-anchor" href="#_3-테마-색상-설정" aria-label="Permalink to &quot;③ 테마 색상 설정&quot;">​</a></h3><p>안내 페이지에 적용할 대표 색상과 강조 색상을 설정합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>Primary Color</td><td>주요 버튼 등의 배경에 사용되는 대표 색상</td></tr><tr><td>Accent Color</td><td>일부 강조 요소에 사용되는 색상</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li><strong>테마 색상</strong> 항목으로 이동합니다.</li><li>Primary Color와 Accent Color를 설정합니다.</li><li>색상 적용 결과를 확인합니다.</li><li>설정을 저장합니다.</li></ol><p>Primary Color는 그라데이션 설정을 지원합니다.</p><blockquote><p><strong>참고</strong></p><p>배경과 글자의 명도 차이가 충분한 색상을 선택하는 것을 권장합니다. 특히 주요 버튼의 색상은 흰색 텍스트와 구분되도록 설정하는 것이 좋습니다.</p></blockquote><h3 id="_4-글꼴-설정" tabindex="-1">④ 글꼴 설정 <a class="header-anchor" href="#_4-글꼴-설정" aria-label="Permalink to &quot;④ 글꼴 설정&quot;">​</a></h3><p>안내 페이지에 적용할 글꼴을 선택할 수 있습니다.</p><p>기본적으로 다음 글꼴을 제공합니다.</p><table tabindex="0"><thead><tr><th>글꼴</th><th>설명</th></tr></thead><tbody><tr><td>SUIT</td><td>간결하고 현대적인 형태의 글꼴</td></tr><tr><td>Pretendard</td><td>다양한 화면에서 가독성이 높은 글꼴</td></tr></tbody></table><p>별도의 글꼴이 필요한 경우 사용자 정의 글꼴을 설정할 수 있습니다.</p><p>사용자 정의 글꼴은 CDN 주소 또는 글꼴 파일을 이용하여 등록할 수 있습니다.</p><p>설정이 완료되면 화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</p><hr><h2 id="_3-4-서비스-모듈-설정" tabindex="-1">3.4. 서비스 모듈 설정 <a class="header-anchor" href="#_3-4-서비스-모듈-설정" aria-label="Permalink to &quot;3.4. 서비스 모듈 설정&quot;">​</a></h2><p>서비스 모듈은 안내 페이지에서 제공할 개별 기능을 의미합니다.</p><p>행사의 운영 목적에 따라 필요한 모듈을 활성화하거나 사용하지 않는 모듈을 비활성화할 수 있습니다.</p><h3 id="_1-모듈-설정-화면-이동" tabindex="-1">① 모듈 설정 화면 이동 <a class="header-anchor" href="#_1-모듈-설정-화면-이동" aria-label="Permalink to &quot;① 모듈 설정 화면 이동&quot;">​</a></h3><ol><li><strong>프로젝트 설정</strong> 메뉴로 이동합니다.</li><li>상단의 <strong>모듈</strong> 항목을 선택합니다.</li><li>현재 활성화된 서비스 모듈을 확인합니다.</li></ol><p><img src="'+p+'" alt="image.png"></p><h3 id="_2-서비스-모듈-안내" tabindex="-1">② 서비스 모듈 안내 <a class="header-anchor" href="#_2-서비스-모듈-안내" aria-label="Permalink to &quot;② 서비스 모듈 안내&quot;">​</a></h3><table tabindex="0"><thead><tr><th>모듈</th><th>설명</th></tr></thead><tbody><tr><td>홈</td><td>행사 소개 및 주요 콘텐츠 제공</td></tr><tr><td>투어맵</td><td>행사 장소 및 시설의 위치 안내</td></tr><tr><td>일정</td><td>행사 및 프로그램 일정 안내</td></tr><tr><td>AI 챗봇</td><td>대화형 행사 정보 안내</td></tr><tr><td>스탬프 투어</td><td>스탬프 수집 및 방문객 참여 기능</td></tr><tr><td>설문</td><td>방문객 설문조사</td></tr><tr><td>비디오 가이드</td><td>영상 기반 안내 콘텐츠</td></tr><tr><td>오디오 가이드</td><td>음성 기반 안내 콘텐츠</td></tr></tbody></table><h3 id="_3-모듈-활성화-및-비활성화" tabindex="-1">③ 모듈 활성화 및 비활성화 <a class="header-anchor" href="#_3-모듈-활성화-및-비활성화" aria-label="Permalink to &quot;③ 모듈 활성화 및 비활성화&quot;">​</a></h3><ol><li>모듈 목록에서 사용할 기능을 확인합니다.</li><li>활성화할 모듈의 체크박스를 선택합니다.</li><li>사용하지 않을 모듈은 체크를 해제합니다.</li><li>화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><strong>모듈 비활성화 시 유의사항</strong></p><p>모듈을 비활성화하면 해당 기능이 숨김 처리되지만, 기존에 입력한 데이터는 삭제되지 않습니다.</p><p>따라서 일시적으로 사용하지 않는 기능은 데이터를 삭제하지 않고 비활성화할 수 있습니다.</p><blockquote><p><strong>참고</strong></p><p>모듈을 활성화하더라도 해당 기능에 필요한 콘텐츠나 세부 설정이 완료되지 않았다면 방문객이 정상적으로 이용하기 어려울 수 있습니다.</p><p>기능을 활성화한 후에는 해당 모듈의 관리 메뉴에서 필요한 정보를 등록해 주세요.</p></blockquote><hr><h2 id="_3-5-하단-내비게이션-설정" tabindex="-1">3.5. 하단 내비게이션 설정 <a class="header-anchor" href="#_3-5-하단-내비게이션-설정" aria-label="Permalink to &quot;3.5. 하단 내비게이션 설정&quot;">​</a></h2><p>하단 내비게이션은 방문객용 안내 페이지의 하단에 표시되는 주요 메뉴입니다.</p><p>사용할 메뉴와 표시 순서, 최초 진입 화면 및 스타일을 설정할 수 있습니다.</p><h3 id="_1-하단-내비게이션-설정-화면-이동" tabindex="-1">① 하단 내비게이션 설정 화면 이동 <a class="header-anchor" href="#_1-하단-내비게이션-설정-화면-이동" aria-label="Permalink to &quot;① 하단 내비게이션 설정 화면 이동&quot;">​</a></h3><ol><li><p>프로젝트 관리 화면에서 <strong>바텀 네비게이션</strong> 메뉴를 선택합니다.</p><p><img src="'+h+'" alt="image.png"></p></li><li><p>현재 설정된 메뉴 목록을 확인합니다.</p></li><li><p>필요한 항목을 수정합니다.</p></li></ol><h3 id="_2-하단-메뉴-구성" tabindex="-1">② 하단 메뉴 구성 <a class="header-anchor" href="#_2-하단-메뉴-구성" aria-label="Permalink to &quot;② 하단 메뉴 구성&quot;">​</a></h3><p>하단 내비게이션에 표시할 메뉴를 선택하고 표시 순서를 설정합니다.</p><p><strong>설정 방법</strong></p><ol><li>메뉴 목록에서 표시할 항목을 선택합니다.</li><li>메뉴 순서를 조정합니다.</li><li>필요한 경우 메뉴별 아이콘을 설정합니다.</li><li>변경 결과를 미리보기에서 확인합니다.</li></ol><p><img src="'+s+'" alt="image.png"></p><h3 id="_3-최초-진입-화면-설정" tabindex="-1">③ 최초 진입 화면 설정 <a class="header-anchor" href="#_3-최초-진입-화면-설정" aria-label="Permalink to &quot;③ 최초 진입 화면 설정&quot;">​</a></h3><p>최초 진입 화면(랜딩 페이지)은 방문객이 안내 페이지에 접속했을 때 처음 표시되는 화면입니다.</p><p>메뉴 중 한개 항목을 랜딩으로 선택하게 되면, 행사 목적에 맞게 적절한 시작 화면을 선택할 수 있습니다.</p><p>예를 들어 행사 정보를 먼저 안내해야 한다면 홈을, 행사장 위치 안내가 중요하다면 투어맵을 시작 화면으로 설정할 수 있습니다.</p><h3 id="_4-하단-내비게이션-스타일-설정" tabindex="-1">④ 하단 내비게이션 스타일 설정 <a class="header-anchor" href="#_4-하단-내비게이션-스타일-설정" aria-label="Permalink to &quot;④ 하단 내비게이션 스타일 설정&quot;">​</a></h3><p>하단 메뉴의 표시 스타일을 설정할 수 있습니다.</p><p>설정 화면에서 제공되는 스타일 옵션을 선택하고, 미리보기를 통해 적용 결과를 확인합니다.</p><p>설정을 마친 후 화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</p><p><img src="'+g+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>하단 내비게이션 설정은 프로젝트의 서비스 모듈 설정과 구분됩니다.</p><p>서비스 모듈에서는 기능의 사용 여부를 설정하고, 바텀 네비게이션에서는 방문객에게 표시할 메뉴와 순서 등을 설정합니다.</p></blockquote><hr><h2 id="_3-6-다국어-설정" tabindex="-1">3.6. 다국어 설정 <a class="header-anchor" href="#_3-6-다국어-설정" aria-label="Permalink to &quot;3.6. 다국어 설정&quot;">​</a></h2><p>인포디오는 다양한 언어를 사용하는 방문객에게 행사 정보를 제공할 수 있도록 다국어 기능을 지원합니다.</p><p>프로젝트 운영자는 행사 특성과 방문객의 언어 환경에 맞게 기본 언어와 지원 언어를 설정할 수 있습니다.</p><h3 id="_1-다국어-설정-화면-이동" tabindex="-1">① 다국어 설정 화면 이동 <a class="header-anchor" href="#_1-다국어-설정-화면-이동" aria-label="Permalink to &quot;① 다국어 설정 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>프로젝트 설정</strong> 메뉴로 이동합니다.</li><li>상단의 <strong>다국어</strong> 항목을 선택합니다.</li><li>현재 설정된 기본 언어 및 지원 언어를 확인합니다.</li></ol><p><img src="'+c+'" alt="image.png"></p><h3 id="_2-기본-언어-설정" tabindex="-1">② 기본 언어 설정 <a class="header-anchor" href="#_2-기본-언어-설정" aria-label="Permalink to &quot;② 기본 언어 설정&quot;">​</a></h3><p>기본 언어는 방문객용 안내 페이지에서 기본적으로 사용되는 언어입니다.</p><p>프로젝트의 주요 방문객에 맞춰 기본 언어를 선택합니다.</p><h3 id="_3-지원-언어-설정" tabindex="-1">③ 지원 언어 설정 <a class="header-anchor" href="#_3-지원-언어-설정" aria-label="Permalink to &quot;③ 지원 언어 설정&quot;">​</a></h3><p>방문객에게 제공할 언어를 선택합니다.</p><p>프로젝트에서 지원하는 언어는 다음과 같습니다.</p><table tabindex="0"><thead><tr><th>언어</th><th>언어 코드</th></tr></thead><tbody><tr><td>한국어</td><td>ko</td></tr><tr><td>영어</td><td>en</td></tr><tr><td>일본어</td><td>ja</td></tr><tr><td>중국어</td><td>zh</td></tr><tr><td>태국어</td><td>th</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>지원할 언어를 선택합니다.</li><li>기본 언어를 지정합니다.</li><li>변경된 설정을 확인합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>지원 언어를 추가한 경우 각 언어에 맞는 콘텐츠를 등록해야 할 수 있습니다.</p><p>방문객에게 제공할 언어별 콘텐츠가 올바르게 표시되는지 확인해 주세요.</p></blockquote><h3 id="_4-다국어-설정-확인" tabindex="-1">④ 다국어 설정 확인 <a class="header-anchor" href="#_4-다국어-설정-확인" aria-label="Permalink to &quot;④ 다국어 설정 확인&quot;">​</a></h3><p>설정 완료 후 방문객용 안내 페이지에 접속하여 언어 선택 및 콘텐츠 표시 상태를 확인합니다.</p><p><img src="'+m+'" alt="image.png"></p><h2 id="_3-7-초기-설정-확인" tabindex="-1">3.7. 초기 설정 확인 <a class="header-anchor" href="#_3-7-초기-설정-확인" aria-label="Permalink to &quot;3.7. 초기 설정 확인&quot;">​</a></h2><p>프로젝트의 기본 정보, 브랜딩, 모듈 및 하단 내비게이션 설정을 완료한 후에는 방문객용 안내 페이지를 확인합니다.</p><h3 id="확인-항목" tabindex="-1">확인 항목 <a class="header-anchor" href="#확인-항목" aria-label="Permalink to &quot;확인 항목&quot;">​</a></h3><ul><li>행사명과 행사 기간이 정확하게 등록되어 있는지 확인</li><li>프로젝트 운영 상태가 적절하게 설정되어 있는지 확인</li><li>로고와 테마 색상이 올바르게 적용되었는지 확인</li><li>선택한 글꼴이 정상적으로 표시되는지 확인</li><li>필요한 서비스 모듈이 활성화되어 있는지 확인</li><li>하단 메뉴와 표시 순서가 올바른지 확인</li><li>최초 진입 화면이 의도한 화면으로 설정되어 있는지 확인</li><li>모바일 환경에서 안내 페이지가 정상적으로 표시되는지 확인</li></ul><p>초기 설정이 완료되면 메인 배너, 상세 콘텐츠, 행사 일정, 지도 등의 정보를 등록하여 안내 페이지를 구성할 수 있습니다.</p><p>자세한 내용은 <strong>4. 안내 페이지 디자인 및 기본 화면 설정</strong>에서 안내합니다.</p>',105)])])}const C=a(_,[["render",b]]);export{j as __pageData,C as default};
